// Role: Build step for hosting (Vercel or Netlify). Writes src/environments/environment.deploy.ts
// from the NBJEWEL_API_URL environment variable of the host, so the deployed app calls the
// deployed .NET API. Used by "npm run build:deploy". The generated file is not committed.
// It holds only the public API address, never a key. When NBJEWEL_API_URL is not set, the app
// is built in sample mode: the customer try-on works with the 6 built-in samples, no API needed.

import { writeFileSync } from 'node:fs';

const url = (process.env.NBJEWEL_API_URL ?? '').trim().replace(/\/+$/, '');
if (url !== '' && !/^https:\/\/[^\s'"`]+$/.test(url)) {
  console.error('Set NBJEWEL_API_URL to the https address of the .NET API, for example https://nbjewel-api.azurewebsites.net');
  process.exit(1);
}
const file = new URL('../src/environments/environment.deploy.ts', import.meta.url);
writeFileSync(file, `// Role: Generated by scripts/write-deploy-env.mjs for hosting. Do not edit or commit.\n\nexport const environment = {\n  apiBaseUrl: '${url}'\n};\n`);
console.log(url ? `API address for this build: ${url}` : 'NBJEWEL_API_URL is not set: building in sample mode (try-on with the 6 built-in samples, owner page off).');
